const generateId = () => Math.random().toString(36).substring(2, 9);

export const useAppStore = create<AppState>()(
    persist(
        (set, get) => ({
            conversations: [],
            activeConversationId: null,
            isLoading: false,
            error: null,
            toastInfo: null,

            feedbackModalState: { isOpen: false },
            isWidgetSimulatorOpen: false,
            isAnalyzerOpen: false,

            attachments: [],
            userUploadedKnowledge: [],

            isAnalyzing: false,
            businessAnalysisResult: null,

            isGeneratingPresentation: false,
            isAnalyzingComparison: false,

            createNewConversation: (mode) => {
                const newConv: Conversation = {
                    id: generateId(),
                    title: 'Nova Conversa',
                    mode: mode,
                    messages: [],
                    createdAt: new Date(),
                };
                set((state) => ({
                    conversations: [newConv, ...state.conversations],
                    activeConversationId: newConv.id,
                    error: null,
                    attachments: [], // Clear attachments on new convo
                }));
            },

            setActiveConversationId: (id) => set({ activeConversationId: id, error: null }),

            deleteConversation: (id) => set((state) => ({
                conversations: state.conversations.filter(c => c.id !== id),
                activeConversationId: state.activeConversationId === id ? null : state.activeConversationId
            })),

            updateConversationTitle: (id, title) => set((state) => ({
                conversations: state.conversations.map(c => c.id === id ? { ...c, title } : c)
            })),

            returnToAgentSelection: () => set({ activeConversationId: null, error: null }),

            addAttachments: async (files) => {
                const newAttachments: Attachment[] = [];
                for (const file of files) {
                    const reader = new FileReader();
                    const base64 = await new Promise<string>((resolve) => {
                        reader.onload = () => resolve(reader.result as string);
                        reader.readAsDataURL(file);
                    });
                    // Remove data URL prefix for API
                    const base64Data = base64.split(',')[1];
                    newAttachments.push({
                        name: file.name,
                        type: file.type,
                        size: file.size,
                        data: base64Data
                    });
                }
                set((state) => ({ attachments: [...state.attachments, ...newAttachments] }));
            },

            removeAttachment: (index) => set((state) => ({
                attachments: state.attachments.filter((_, i) => i !== index)
            })),

            submitQuery: async (prompt) => {
                const state = get();
                const { activeConversationId, conversations, attachments, userUploadedKnowledge } = state;

                if (!activeConversationId) return;

                const currentConvo = conversations.find(c => c.id === activeConversationId);
                if (!currentConvo) return;

                // Add user message
                const userMsg: Message = {
                    role: 'user',
                    content: prompt,
                    attachments: attachments.length > 0 ? [...attachments] : undefined
                };

                const updatedMessages = [...currentConvo.messages, userMsg];

                // Optimistically update UI
                set((state) => ({
                    conversations: state.conversations.map(c => c.id === activeConversationId ? { ...c, messages: updatedMessages } : c),
                    isLoading: true,
                    error: null,
                    attachments: [] // Clear attachments after sending
                }));

                // Generate title if first message
                if (currentConvo.messages.length === 0) {
                    generateConversationTitle(prompt).then(title => {
                        set((state) => ({
                            conversations: state.conversations.map(c => c.id === activeConversationId ? { ...c, title } : c)
                        }));
                    });
                }

                const abortController = new AbortController();
                // Store controller if needed for stop functionality (simplified here)

                try {
                    // Logic based on mode
                    const mode = currentConvo.mode;
                    let agentResponseContent: any = '';

                    // Modes that return JSON by default
                    const jsonModes = [AppMode.PAGE, AppMode.MARKET_INTEL, AppMode.BLOG_POST, AppMode.PORTFOLIO_SEARCH, AppMode.CONTENT_PLANNER, AppMode.LEAD_HUNTER, AppMode.PRESENTATION_BUILDER];
                    const isFirstDossierMessage = mode === AppMode.CUSTOMER_DOSSIER && currentConvo.messages.length === 0; // Fixed logic

                    if (mode === AppMode.IMAGE_ADS) {
                        const adPackage = await generateImageAd(prompt, userMsg.attachments);
                        agentResponseContent = adPackage;
                    } else if (isFirstDossierMessage) {
                        // Dossier specific flow
                        const dossier = await runDossierQuery([...updatedMessages], abortController.signal);
                        agentResponseContent = dossier;
                    } else if (jsonModes.includes(mode)) {
                        const result = await runGeminiJsonQuery(mode, updatedMessages, abortController.signal, { userKnowledge: userUploadedKnowledge });
                        agentResponseContent = result;

                        // Handle side effects for tools
                        if (mode === AppMode.PRESENTATION_BUILDER && isPresentationPackage(result)) {
                            set((state) => ({
                                conversations: state.conversations.map(c => c.id === activeConversationId ? { ...c, presentationPackage: result } : c)
                            }));
                        } else if (mode === AppMode.PORTFOLIO_SEARCH && isPortfolioSearchResult(result)) {
                             set((state) => ({
                                conversations: state.conversations.map(c => c.id === activeConversationId ? { 
                                    ...c, 
                                    portfolioSearchQuery: prompt,
                                    portfolioSearchResults: result 
                                } : c)
                            }));
                        } else if (mode === AppMode.CONTENT_PLANNER && isContentPlan(result)) {
                             set((state) => ({
                                conversations: state.conversations.map(c => c.id === activeConversationId ? { ...c, contentPlan: result } : c)
                            }));
                        }

                    } else {
                        // Streaming text response
                        const agentMsgPlaceholder: Message = { role: 'agent', content: '' };
                        set((state) => ({
                            conversations: state.conversations.map(c => c.id === activeConversationId ? {
                                ...c,
                                messages: [...updatedMessages, agentMsgPlaceholder]
                            } : c)
                        }));

                        const stream = streamGeminiQuery(mode, updatedMessages, abortController.signal, { userKnowledge: userUploadedKnowledge });

                        for await (const chunk of stream) {
                            agentResponseContent += chunk;
                            set((state) => {
                                const convo = state.conversations.find(c => c.id === activeConversationId);
                                if (!convo) return state;
                                const msgs = [...convo.messages];
                                const lastMsg = msgs[msgs.length - 1];
                                if (lastMsg.role === 'agent') {
                                    lastMsg.content = agentResponseContent;
                                }
                                return {
                                    conversations: state.conversations.map(c => c.id === activeConversationId ? { ...c, messages: msgs } : c)
                                };
                            });
                        }
                        return; // Done with streaming
                    }

                    // For non-streaming (JSON or Image) responses, add the final message
                    set((state) => {
                        const convo = state.conversations.find(c => c.id === activeConversationId);
                        if (!convo) return state;
                        return {
                            conversations: state.conversations.map(c => c.id === activeConversationId ? {
                                ...c,
                                messages: [...convo.messages, { role: 'agent', content: agentResponseContent }]
                            } : c),
                            isLoading: false
                        };
                    });

                } catch (err: any) {
                    console.error(err);
                    set({ error: err.message || "Ocorreu um erro ao processar sua solicitação.", isLoading: false });
                } finally {
                    set({ isLoading: false });
                }
            },

            stopGeneration: () => {
                // In a real implementation, we would abort the AbortController here.
                // For simplicity in this reconstruction, we just reset loading state.
                set({ isLoading: false });
            },

            showToast: (message, type, duration) => set({ toastInfo: { message, type, duration } }),
            hideToast: () => set({ toastInfo: null }),

            openFeedbackModal: (conversationId, messageIndex) => set({ feedbackModalState: { isOpen: true, conversationId, messageIndex } }),
            closeFeedbackModal: () => set({ feedbackModalState: { isOpen: false } }),
            submitNegativeFeedback: (reason) => {
                // Mock submission
                console.log("Negative feedback:", reason);
                get().showToast("Obrigado pelo seu feedback!", "success");
                get().closeFeedbackModal();
            },
            setMessageFeedback: (conversationId, messageIndex, type) => set((state) => {
                const convo = state.conversations.find(c => c.id === conversationId);
                if (!convo) return state;
                const msgs = [...convo.messages];
                if (msgs[messageIndex]) {
                    msgs[messageIndex].feedback = { type };
                    if (type === 'bad') {
                        // Open feedback modal for details
                        return { 
                            conversations: state.conversations.map(c => c.id === conversationId ? { ...c, messages: msgs } : c),
                            feedbackModalState: { isOpen: true, conversationId, messageIndex }
                        };
                    }
                }
                return { conversations: state.conversations.map(c => c.id === conversationId ? { ...c, messages: msgs } : c) };
            }),

            setWidgetSimulatorOpen: (isOpen) => set({ isWidgetSimulatorOpen: isOpen }),
