                    const messages: Message[] = [{ role: 'user', content: prompt }];
                    const result = await runGeminiJsonQuery(AppMode.CONTENT_PLANNER, messages, new AbortController().signal);

                    if (isContentPlan(result)) {
                        set((state) => ({
                            conversations: state.conversations.map(c => c.id === state.activeConversationId ? { ...c, contentPlan: result } : c),
                            isLoading: false
                        }));
                    } else {
                        throw new Error("Formato inválido recebido.");
                    }
                } catch (e: any) {
                    set({ isLoading: false, error: e.message });
                }
            },

            executeContentPlanItem: (briefing, platform) => {
                // Create new conversation in Content mode and send briefing
                get().createNewConversation(AppMode.CONTENT);
                const prompt = `Crie um conteúdo para ${platform} com o seguinte briefing: ${briefing}`;
                setTimeout(() => get().submitQuery(prompt), 100);
            },

            toggleContentPlanItemStatus: (convoId, itemId) => set((state) => {
                const convo = state.conversations.find(c => c.id === convoId);
                if (!convo || !convo.contentPlan) return state;

                const newItems = convo.contentPlan.items.map(item => 
                    item.id === itemId ? { ...item, isCompleted: !item.isCompleted } : item
                );

                return {
                    conversations: state.conversations.map(c => c.id === convoId ? {
                        ...c,
                        contentPlan: { ...convo.contentPlan!, items: newItems }
                    } : c)
                };
            })
        }),
        {
            name: 'app-storage',
            storage: createJSONStorage(() => localStorage),
            partialize: (state) => ({ 
                conversations: state.conversations, 
                activeConversationId: state.activeConversationId,
                userUploadedKnowledge: state.userUploadedKnowledge
            }),
        }
    )
);

