interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose }) => {
  const { 
    conversations, 
    activeConversationId, 
    setActiveConversationId, 
    deleteConversation,
    updateConversationTitle,
    returnToAgentSelection,
    createNewConversation,
