import { read, utils } from 'xlsx';

export const extractTextFromExcel = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });

                let fullText = `Conteúdo do Arquivo: ${file.name}\n\n`;

                // Iterate over all sheets
                workbook.SheetNames.forEach(sheetName => {
                    const worksheet = workbook.Sheets[sheetName];
                    // Convert sheet to JSON array of arrays (rows)
                    const sheetData = utils.sheet_to_json(worksheet, { header: 1 });

                    if (sheetData.length > 0) {
                        fullText += `--- Aba: ${sheetName} ---\n`;
                        // Format rows as pipe-separated text for clear AI reading
                        fullText += sheetData.map((row: any) => {
                            if (Array.isArray(row)) {
                                return row.join(' | ');
                            }
                            return String(row);
                        }).join('\n');
                        fullText += '\n\n';
                    }
                });

                resolve(fullText);
            } catch (err) {
                console.error("Excel parsing error:", err);
                reject(new Error("Falha ao ler o arquivo Excel. Verifique se o formato está correto."));
            }
        };

        reader.onerror = () => reject(new Error("Erro ao ler o arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

import React, { useState, useMemo, useRef } from 'react';
import { useAppStore } from '../store/useAppStore';
import { SubmitButton } from './ui/SubmitButton';
import OutboundDashboard from './OutboundDashboard';
import Loader from './Loader';
import { extractTextFromExcel } from '../services/excelService';

const OutboundStrategist: React.FC = () => {
    const { 
        activeConversationId, 
        conversations, 
        isAnalyzingOutbound, 
        error, 
        runOutboundAnalysis 
    } = useAppStore();

    const conversation = useMemo(() => conversations.find(c => c.id === activeConversationId), [conversations, activeConversationId]);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [isDragOver, setIsDragOver] = useState(false);
    const [localLoading, setLocalLoading] = useState(false);

    const handleFileProcess = async (file: File) => {
        setLocalLoading(true);
        try {
            let textContent = '';
            const fileNameLower = file.name.toLowerCase();

            if (fileNameLower.endsWith('.xlsx') || fileNameLower.endsWith('.xls') || fileNameLower.endsWith('.csv')) {
                // Real parsing for Excel/CSV
                textContent = await extractTextFromExcel(file);
            } else if (fileNameLower.endsWith('.pdf')) {
                // Mock for PDF (Client-side PDF parsing is complex without heavy libs like pdf.js)
                // In a production app, we would send this to a backend or use pdf.js
                textContent = `[Simulação de Leitura de PDF para o arquivo: ${file.name}]\n
                Vendedor: Ricardo Souza

                Atividades da Semana:
                - 10/10: Ligação para Provedor XYZ (Interesse em OLT Chassi, mas achou caro).
                - 10/10: Proposta enviada para ABC Telecom (200 ONUs).
                - 11/10: Reunião com LinkBR. Fechamento provável.
                - 12/10: Prospecção fria. 15 ligações, 2 interessados.
                - 13/10: Follow-up cliente antigo (NetFast). Recompra de cabos drop.

                Total Vendas: R$ 45.000,00
                Meta: R$ 80.000,00
                `;
            } else {
                throw new Error("Formato de arquivo não suportado. Use .xlsx, .xls, .csv ou .pdf");
            }

            if (!textContent.trim()) {
                throw new Error("O arquivo parece estar vazio.");
            }

            await runOutboundAnalysis(textContent);
        } catch (e: any) {
            console.error(e);
            alert(e.message || "Erro ao processar arquivo");
        } finally {
            setLocalLoading(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            handleFileProcess(e.target.files[0]);
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            handleFileProcess(e.dataTransfer.files[0]);
        }
    };

    if (conversation?.outboundReport) {
        return (
            <div className="h-full p-4 sm:p-6 overflow-y-auto custom-scrollbar bg-white">
                <OutboundDashboard report={conversation.outboundReport} />
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col items-center justify-center p-4 bg-greatek-bg-light/50 animate-fade-in overflow-y-auto">
            {isAnalyzingOutbound || localLoading ? (
                <Loader />
            ) : (
                <div className="max-w-2xl w-full bg-white p-8 rounded-xl shadow-lg border border-greatek-border text-center my-auto">
                    <div className="mb-6">
                        <div className="w-16 h-16 bg-greatek-blue/10 rounded-2xl flex items-center justify-center mx-auto mb-4">
                            <i className="bi bi-telephone-outbound-fill text-4xl text-greatek-blue"></i>
                        </div>
                        <h1 className="text-2xl font-bold text-greatek-dark-blue">Estrategista de Outbound</h1>
                        <p className="text-text-secondary mt-2">
                            Faça o upload do <strong>Registro de Atividades (Ploomes)</strong> em Excel ou CSV. 
                            A IA analisará os dados reais da planilha para gerar a Curva ABC, Planejamento Semanal e Relatório Gerencial.
                        </p>
                    </div>

                    <div 
                        className={`p-10 border-2 border-dashed rounded-xl cursor-pointer transition-all duration-300 ${isDragOver ? 'border-greatek-blue bg-greatek-blue/5 scale-105' : 'border-gray-300 hover:border-greatek-blue hover:bg-gray-50'}`}
                        onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
                        onDragLeave={() => setIsDragOver(false)}
                        onDrop={handleDrop}
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            className="hidden" 
                            accept=".xlsx,.xls,.csv,.pdf" 
                            onChange={handleFileChange}
                        />
                        <i className="bi bi-file-earmark-spreadsheet-fill text-5xl text-green-600 mb-4 block"></i>
                        <span className="text-lg font-semibold text-greatek-dark-blue">Clique para fazer upload</span>
                        <p className="text-sm text-text-secondary mt-1">Suporta Excel (.xlsx, .xls), CSV e PDF</p>
                    </div>

                    {error && (
                        <div className="mt-4 p-3 bg-red-50 text-red-700 text-sm rounded-lg border border-red-200">
                            {error}
                        </div>
                    )}

                    <p className="text-xs text-text-secondary/60 mt-6">
                        * A análise processa o arquivo localmente. Certifique-se que o arquivo contém colunas como "Cliente", "Atividade", "Produto" ou "Valor".
                    </p>
                </div>
            )}
        </div>
    );
};

