            set(state => ({
                conversations: state.conversations.map(c => c.id === state.activeConversationId ? { ...c, comparisonAnalysis: text } : c)
            }));
        }
        set({ isAnalyzingComparison: false });
    },

    createImageAdFromPrompt: (prompt) => {
