                                <p className="text-xs text-white/70 italic">"{currentReport.management_report.action_plan_summary}"</p>
                            </div>
                        </div>
                    </div>
                </section>
            </main>

            {/* Modal de Email */}
            <Modal isOpen={isEmailModalOpen} onClose={() => setIsEmailModalOpen(false)} title={`Enviar Plano: ${currentReport.salesperson_name}`}>
                <div className="space-y-4">
                    <p className="text-sm text-text-secondary">
                        Envie o planejamento semanal e as metas diretamente para o e-mail do vendedor <strong>{currentReport.salesperson_name}</strong>.
                    </p>
                    <div>
                        <label className="block text-sm font-semibold text-greatek-dark-blue mb-1">E-mail do Vendedor</label>
                        <input 
                            type="email" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
