const GoalInputScreen: React.FC<{ 
    sellerName: string; 
    onSetGoal: (value: number) => void; 
}> = ({ sellerName, onSetGoal }) => {
    const [inputValue, setInputValue] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const numericValue = parseFloat(inputValue.replace(/\./g, '').replace(',', '.'));
        if (!isNaN(numericValue) && numericValue > 0) {
            onSetGoal(numericValue);
        }
    };

    const handleCurrencyChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const raw = e.target.value.replace(/\D/g, '');
        const formatted = (Number(raw) / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        setInputValue(formatted);
    };

    return (
        <div className="flex flex-col items-center justify-center p-12 bg-white rounded-xl border border-dashed border-greatek-blue/30 shadow-sm animate-fade-in">
            <div className="w-16 h-16 bg-greatek-blue/10 rounded-full flex items-center justify-center mb-6">
                <i className="bi bi-calculator-fill text-3xl text-greatek-blue"></i>
            </div>
            <h3 className="text-xl font-bold text-greatek-dark-blue mb-2">Defina a Meta Mensal</h3>
            <p className="text-text-secondary text-center mb-6 max-w-md">
                Para que a IA possa calcular as metas semanais e o ticket ideal de <strong>{sellerName}</strong>, precisamos saber qual é o objetivo financeiro deste mês.
            </p>
            <form onSubmit={handleSubmit} className="flex gap-2 w-full max-w-sm">
                <div className="relative flex-grow">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 font-semibold">R$</span>
                    <input 
                        type="text" 
                        value={inputValue}
                        onChange={handleCurrencyChange}
                        className="w-full pl-10 pr-4 py-3 border border-greatek-border rounded-lg focus:ring-2 focus:ring-greatek-blue focus:border-transparent text-lg font-bold text-greatek-dark-blue"
                        placeholder="0,00"
                        autoFocus
                    />
                </div>
                <button 
                    type="submit"
                    disabled={!inputValue || inputValue === '0,00'}
                    className="bg-greatek-blue text-white px-6 py-3 rounded-lg font-bold hover:bg-greatek-dark-blue transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    Calcular
                </button>
            </form>
        </div>
    );
};

