const OutboundDashboard: React.FC<{ report: OutboundReport[] }> = ({ report }) => {
    const [selectedSellerIndex, setSelectedSellerIndex] = useState(0);
    const [sellerGoals, setSellerGoals] = useState<Record<number, { goal: number, days: number }>>({});
    const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
    const [email, setEmail] = useState('');
    const { sendOutboundPlanEmail } = useAppStore();

    const currentReport = useMemo(() => report[selectedSellerIndex], [report, selectedSellerIndex]);
    const currentGoalData = sellerGoals[selectedSellerIndex];

    const handleSetGoal = (goal: number, days: number) => {
        setSellerGoals(prev => ({ ...prev, [selectedSellerIndex]: { goal, days } }));
    };

    // Cálculos de Engenharia Reversa
    const calculatedTargets: CalculatedTargets | null = useMemo(() => {
        if (!currentGoalData) return null;

        // Tentar extrair Ticket Médio do relatório da IA ou usar padrão
        // A IA pode ter colocado "Ticket Médio: R$ 5.000" no texto de análise. 
        // Por simplicidade, usamos um padrão ajustável ou extração simples se houver.
        const ticket = DEFAULT_TICKET; 

        const { goal, days } = currentGoalData;

        // 1. Quanto precisa vender por dia?
        const dailySale = goal / days;

        // 2. Quantas propostas precisa ganhar por dia?
        const dailyWins = dailySale / ticket;

        // 3. Quantas propostas precisa enviar? (Baseado na conversão)
        const dailyProposals = dailyWins / DEFAULT_CONVERSION_RATE;

        // 4. Quantas ligações precisa fazer? (Baseado na taxa de conversão de chamada em proposta)
        const dailyCalls = dailyProposals / DEFAULT_CALLS_TO_PROPOSAL_RATE;

        return {
            dailySalesNeeded: dailySale,
            dailyProposalsNeeded: dailyProposals,
            dailyCallsNeeded: dailyCalls,
            ticketUsed: ticket
        };

    }, [currentGoalData]);

    const handleSendEmail = () => {
        if (email && currentReport && calculatedTargets) {
            const emailData = {
                ...currentReport.action_report,
                calculated_targets: {
                    meta_restante: formatCurrency(currentGoalData.goal),
                    dias_uteis: currentGoalData.days,
                    ligacoes_diarias: Math.ceil(calculatedTargets.dailyCallsNeeded),
                    propostas_diarias: Math.ceil(calculatedTargets.dailyProposalsNeeded),
                    vendas_diarias: formatCurrency(calculatedTargets.dailySalesNeeded)
                }
            };
            sendOutboundPlanEmail(email, emailData);
            setIsEmailModalOpen(false);
            setEmail('');
        }
    };

    if (!currentReport) return null;

    return (
        <div className="flex flex-col h-full bg-greatek-bg-light/30">
            {/* Header com Abas */}
            <div className="bg-white border-b border-greatek-border pt-4 px-4 sticky top-0 z-10 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                    <div>
                        <h2 className="text-xl font-bold text-greatek-dark-blue">Estratégia Hunter</h2>
                        <p className="text-xs text-text-secondary mt-1">Transformando tiradores de pedido em caçadores de oportunidades.</p>
                    </div>
                    {currentGoalData && (
                        <button 
                            onClick={() => setIsEmailModalOpen(true)}
                            className="flex items-center gap-2 bg-white border border-greatek-border text-text-secondary px-3 py-1.5 rounded-lg text-xs font-semibold hover:bg-gray-50 transition-colors shadow-sm"
                        >
                            <i className="bi bi-envelope-paper"></i>
                            Enviar Plano
                        </button>
                    )}
                </div>

                <div className="flex overflow-x-auto custom-scrollbar gap-1">
                    {report.map((item, index) => (
                        <button
