import { read, utils } from 'xlsx';

export const extractTextFromExcel = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = read(data, { type: 'array' });

                let fullText = `NOME DO ARQUIVO: ${file.name}\n\n`;

                // Iterate over all sheets
                workbook.SheetNames.forEach(sheetName => {
                    const worksheet = workbook.Sheets[sheetName];

                    // Convert sheet to JSON with alphabetical headers (A, B, C...)
                    // This creates an array of objects like: [{ "A": "Data", "B": "Vendedor", "C": "Histórico com, virgulas" }]
                    // This is strictly safer than CSV for text-heavy content (conversations).
                    const jsonData = utils.sheet_to_json(worksheet, { 
                        header: "A", // Forces keys to be A, B, C, D... aligning with Prompt instructions
                        defval: ""   // Ensures empty cells are present to maintain column alignment
                    });

                    if (jsonData && jsonData.length > 0) {
                        fullText += `=== PLANILHA (ABA): ${sheetName} ===\n`;
                        fullText += `[INÍCIO DOS DADOS ESTRUTURADOS (JSON) - Colunas mapeadas por Letras]\n`;
                        // Using pretty print (null, 2) makes it readable for debugging but slightly more tokens.
                        // For the LLM, the structure is what matters.
                        fullText += JSON.stringify(jsonData, null, 2);
                        fullText += `\n[FIM DOS DADOS ESTRUTURADOS]\n\n`;
                    }
                });

                resolve(fullText);
            } catch (err) {
                console.error("Excel parsing error:", err);
                reject(new Error("Falha ao ler o arquivo Excel. Verifique se o formato está correto."));
            }
        };

        reader.onerror = () => reject(new Error("Erro ao ler o arquivo."));
        reader.readAsArrayBuffer(file);
    });
};

