const WeeklyPlanBento: React.FC<{ 
    plan: OutboundDailyPlan[]; 
    targets: CalculatedTargets;
}> = ({ plan, targets }) => {

    // Função para determinar o estilo com base no dia (0-4)
    const getDayStyle = (index: number) => {
        switch(index) {
            case 0: // Segunda (Hero - Ataque Total)
                return {
                    gridClass: "md:col-span-2 md:row-span-2 min-h-[320px]",
                    bgColor: "bg-white",
                    borderColor: "border-l-8 border-l-greatek-blue border-y-gray-200 border-r-gray-200",
                    icon: "bi-rocket-takeoff-fill",
                    headerColor: "text-greatek-blue",
                    intensity: "Alta Intensidade"
                };
            case 1: // Terça (Ataque)
            case 2: // Quarta (Ataque)
                return {
                    gridClass: "md:col-span-1 md:row-span-1",
                    bgColor: "bg-white",
                    borderColor: "border-gray-200",
                    icon: "bi-lightning-charge-fill",
                    headerColor: "text-greatek-dark-blue",
                    intensity: "Foco Hunter"
                };
            case 3: // Quinta (Revisão/Admin)
                return {
                    gridClass: "md:col-span-1 md:row-span-1 opacity-90",
                    bgColor: "bg-purple-50",
                    borderColor: "border-purple-200",
                    icon: "bi-kanban",
                    headerColor: "text-purple-700",
                    intensity: "Follow-up & Admin"
                };
            case 4: // Sexta (Planejamento)
                return {
                    gridClass: "md:col-span-1 md:row-span-1 opacity-90",
                    bgColor: "bg-indigo-50",
                    borderColor: "border-indigo-200",
                    icon: "bi-calendar-check",
                    headerColor: "text-indigo-700",
                    intensity: "Revisão & Próx. Semana"
                };
            default:
                return { gridClass: "", bgColor: "bg-white", borderColor: "border-gray-200", icon: "", headerColor: "", intensity: "" };
        }
    };

    // Ajuste de metas baseado no dia da semana (Seg-Qua mais pesado, Qui-Sex mais leve)
    const getAdjustedTarget = (base: number, dayIndex: number) => {
        // Seg, Ter, Qua: 120% da meta diária média
        // Qui, Sex: 70% da meta diária média (foco em qualidade/admin)
        const factor = dayIndex <= 2 ? 1.2 : 0.7; 
        return Math.ceil(base * factor);
    };

    return (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {plan.map((day, idx) => {
                const style = getDayStyle(idx);
                const callsGoal = getAdjustedTarget(targets.dailyCallsNeeded, idx);
                const proposalsGoal = getAdjustedTarget(targets.dailyProposalsNeeded, idx);

                return (
                    <BentoGridItem 
                        key={idx} 
                        className={style.gridClass}
                        title={`${day.day}`}
                        icon={style.icon}
                        headerColor={style.headerColor}
                        bgColor={style.bgColor}
                        borderColor={style.borderColor}
                    >
                        <div className="flex justify-between items-center mb-4">
                            <span className="text-[10px] font-bold uppercase tracking-widest bg-gray-100 px-2 py-1 rounded text-gray-500">
                                {style.intensity}
                            </span>
                            {idx <= 2 && (
                                <span className="text-[10px] font-bold text-red-500 flex items-center animate-pulse">
                                    <i className="bi bi-record-fill mr-1"></i> Foco Vendas
                                </span>
                            )}
                        </div>

                        {/* Metricas diferem se for dia de ataque ou revisão */}
                        <div className="grid grid-cols-2 gap-2 mb-4">
                            <DailyMetricsBadge 
                                label={idx <= 2 ? "Ligações (Meta)" : "Follow-ups"} 
                                value={callsGoal} 
                                color={idx <= 2 ? "bg-blue-100" : "bg-purple-100"} 
                                textColor={idx <= 2 ? "text-blue-800" : "text-purple-800"}
                            />
                            <DailyMetricsBadge 
                                label={idx <= 2 ? "Propostas (Meta)" : "Recuperação"} 
                                value={proposalsGoal} 
                                color={idx <= 2 ? "bg-green-100" : "bg-indigo-100"} 
                                textColor={idx <= 2 ? "text-green-800" : "text-indigo-800"}
                            />
                        </div>

                        <div className="space-y-3 flex-grow">
                            {day.focus_products.length > 0 && (
                                <div>
                                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1"><i className="bi bi-crosshair"></i> Foco do Dia</p>
                                    <div className="flex flex-wrap gap-1">
                                        {day.focus_products.map((p, i) => (
                                            <span key={i} className="text-[10px] bg-white border border-gray-200 text-gray-600 px-2 py-1 rounded shadow-sm">{p}</span>
                                        ))}
                                    </div>
                                </div>
                            )}

                            <div className={`${idx <= 2 ? 'bg-gray-50' : 'bg-white/50'} p-3 rounded border border-gray-100/50 h-full`}>
                                <p className="text-[10px] font-bold text-gray-400 uppercase mb-2"><i className="bi bi-list-check"></i> Tarefas Prioritárias</p>
                                <ul className="space-y-2">
                                    {day.key_actions.map((a, i) => (
                                        <li key={i} className="text-xs text-text-secondary leading-tight flex items-start">
                                            <i className={`bi bi-check-circle-fill mr-2 mt-0.5 text-[10px] ${idx <= 2 ? 'text-green-500' : 'text-purple-400'}`}></i> 
                                            {a}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    </BentoGridItem>
                );
            })}
        </div>
    );
};

