const GoalInputScreen: React.FC<{ 
    sellerName: string; 
    onSetGoal: (inputs: UserGoalInputs) => void; 
}> = ({ sellerName, onSetGoal }) => {
    const [goal, setGoal] = useState('');
    const [days, setDays] = useState('20');
    const [ticket, setTicket] = useState('5000,00');
    const [conversion, setConversion] = useState('20');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        const numGoal = parseFloat(goal.replace(/\./g, '').replace(',', '.'));
        const numDays = parseInt(days);
        const numTicket = parseFloat(ticket.replace(/\./g, '').replace(',', '.'));
        const numConv = parseFloat(conversion);

        if (numGoal > 0 && numDays > 0 && numTicket > 0 && numConv > 0) {
            onSetGoal({
                goal: numGoal,
                days: numDays,
                avgTicket: numTicket,
                conversionRate: numConv
            });
        }
    };

    const formatMoney = (val: string) => {
        const raw = val.replace(/\D/g, '');
        return (Number(raw) / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
    };

    return (
        <div className="flex flex-col items-center justify-center p-8 bg-white rounded-xl border border-dashed border-greatek-blue/30 shadow-sm animate-fade-in my-8">
            <div className="w-12 h-12 bg-greatek-blue/10 rounded-full flex items-center justify-center mb-3">
                <i className="bi bi-sliders text-2xl text-greatek-blue"></i>
            </div>
            <h3 className="text-lg font-bold text-greatek-dark-blue mb-1">Calibragem de Meta: {sellerName}</h3>
            <p className="text-xs text-text-secondary text-center mb-6 max-w-md">
                Insira os dados reais para que a IA calcule a intensidade de prospecção necessária.
            </p>

            <form onSubmit={handleSubmit} className="w-full max-w-2xl grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-greatek-dark-blue mb-1 uppercase">Meta Financeira (R$)</label>
                    <input 
                        type="text" 
                        value={goal}
                        onChange={(e) => setGoal(formatMoney(e.target.value))}
                        className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black font-bold"
                        placeholder="0,00"
                        autoFocus
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-greatek-dark-blue mb-1 uppercase">Ticket Médio (R$)</label>
                    <input 
                        type="text" 
                        value={ticket}
                        onChange={(e) => setTicket(formatMoney(e.target.value))}
                        className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black font-bold"
                        placeholder="0,00"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-greatek-dark-blue mb-1 uppercase">Dias Úteis Restantes</label>
                    <input 
                        type="number" 
                        value={days}
                        onChange={(e) => setDays(e.target.value)}
                        className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black font-bold"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-greatek-dark-blue mb-1 uppercase">Taxa de Conversão Proposta (%)</label>
                    <input 
                        type="number" 
                        value={conversion}
                        onChange={(e) => setConversion(e.target.value)}
                        className="w-full p-2.5 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black font-bold"
                        placeholder="20"
                    />
                </div>

                <div className="sm:col-span-2 pt-2">
                    <button 
                        type="submit"
                        disabled={!goal || goal === '0,00'}
                        className="w-full bg-greatek-blue text-white py-3 rounded-lg font-bold hover:bg-greatek-dark-blue transition-colors shadow-sm"
                    >
                        Gerar Planejamento Matemático
                    </button>
                </div>
            </form>
        </div>
    );
};

const OutboundDashboard: React.FC<{ report: OutboundReport[] }> = ({ report }) => {
    const [selectedSellerIndex, setSelectedSellerIndex] = useState(0);
    const [sellerGoals, setSellerGoals] = useState<Record<number, UserGoalInputs>>({});
    const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
    const [email, setEmail] = useState('');
    const { sendOutboundPlanEmail } = useAppStore();

    const currentReport = useMemo(() => report[selectedSellerIndex], [report, selectedSellerIndex]);
    const currentInputs = sellerGoals[selectedSellerIndex];

    const handleSetGoal = (inputs: UserGoalInputs) => {
        setSellerGoals(prev => ({ ...prev, [selectedSellerIndex]: inputs }));
    };

    // Cálculos de Engenharia Reversa (Corrigidos e Precisos)
    const calculatedTargets: CalculatedTargets | null = useMemo(() => {
        if (!currentInputs) return null;

        const { goal, days, avgTicket, conversionRate } = currentInputs;

        // 1. Meta Diária Financeira
        const dailySales = goal / days;

        // 2. Quantas VENDAS (Deals) por dia?
        const dailyDeals = dailySales / avgTicket;

        // 3. Quantas PROPOSTAS por dia? (Baseado na conversão inputada)
        // Ex: Preciso de 5 vendas. Conversão é 20% (0.2). Propostas = 5 / 0.2 = 25.
        const dailyProposals = dailyDeals / (conversionRate / 100);

        // 4. Quantas LIGAÇÕES por dia? (Assumindo que 30% das ligações viram proposta - Fator fixo de mercado ou ajustável no futuro)
        const CONTACT_TO_PROPOSAL_RATIO = 0.30; 
        const dailyCalls = dailyProposals / CONTACT_TO_PROPOSAL_RATIO;

        return {
            dailySalesNeeded: dailySales,
            dailyDealsNeeded: dailyDeals,
            dailyProposalsNeeded: dailyProposals,
            dailyCallsNeeded: dailyCalls
        };

    }, [currentInputs]);

    const handleSendEmail = () => {
        if (email && currentReport && calculatedTargets) {
            const emailData = {
                ...currentReport.action_report,
                calculated_targets: {
                    meta_restante: formatCurrency(currentInputs.goal),
                    dias_uteis: currentInputs.days,
                    ligacoes_diarias: Math.ceil(calculatedTargets.dailyCallsNeeded),
                    propostas_diarias: Math.ceil(calculatedTargets.dailyProposalsNeeded),
                    vendas_diarias: formatCurrency(calculatedTargets.dailySalesNeeded)
                }
            };
            sendOutboundPlanEmail(email, emailData);
            setIsEmailModalOpen(false);
            setEmail('');
        }
    };

    if (!currentReport) return null;

    return (
        <div className="flex flex-col h-full bg-greatek-bg-light/30">
            {/* Header com Abas */}
            <div className="bg-white border-b border-greatek-border pt-4 px-4 sticky top-0 z-10 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                    <div>
                        <h2 className="text-xl font-bold text-greatek-dark-blue">Estratégia Outbound</h2>
                        <p className="text-xs text-text-secondary mt-1">Análise de Performance e Planejamento Hunter.</p>
                    </div>
                    {currentInputs && (
                        <button 
                            onClick={() => setIsEmailModalOpen(true)}
                            className="flex items-center gap-2 bg-white border border-greatek-border text-text-secondary px-3 py-1.5 rounded-lg text-xs font-semibold hover:bg-gray-50 transition-colors shadow-sm"
                        >
                            <i className="bi bi-envelope-paper"></i>
                            Enviar Plano
                        </button>
                    )}
                </div>

                <div className="flex overflow-x-auto custom-scrollbar gap-1">
                    {report.map((item, index) => (
                        <button
                            key={index}
                            onClick={() => setSelectedSellerIndex(index)}
                            className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${
                                selectedSellerIndex === index
                                    ? 'border-greatek-blue text-greatek-blue bg-blue-50/50 rounded-t-lg'
                                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50 rounded-t-lg'
                            }`}
                        >
                            <i className="bi bi-person-badge"></i>
                            {item.salesperson_name}
                            {sellerGoals[index] ? (
                                <i className="bi bi-check-circle-fill text-green-500 text-[10px] ml-1"></i>
                            ) : (
                                <i className="bi bi-exclamation-circle-fill text-yellow-500 text-[10px] ml-1"></i>
                            )}
                        </button>
                    ))}
                </div>
            </div>

            <main className="flex-grow p-4 sm:p-6 overflow-y-auto custom-scrollbar">

                {/* 1. Carteira de Clientes */}
                <section className="mb-8">
                    <h3 className="text-base font-bold text-greatek-dark-blue mb-4 flex items-center">
                        <i className="bi bi-funnel-fill text-greatek-blue mr-2"></i>
                        Oportunidades no Radar (Baseado no Relatório Enviado)
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 h-[500px]">
                        <AbcColumn 
                            title="Curva A (Alta Prioridade)" 
                            contacts={currentReport.abc_curve.weekly_contacts} 
                            color="border-green-500" 
                            icon="bi-star-fill text-green-600"
                            subtext="Clientes em negociação ativa ou alto potencial."
                        />
                        <AbcColumn 
                            title="Curva B (Média Prioridade)" 
                            contacts={currentReport.abc_curve.biweekly_contacts} 
                            color="border-yellow-500" 
                            icon="bi-bookmark-star-fill text-yellow-600"
                            subtext="Clientes em nutrição ou follow-up."
                        />
                        <AbcColumn 
                            title="Curva C (Baixa Prioridade)" 
                            contacts={currentReport.abc_curve.monthly_contacts} 
                            color="border-gray-400" 
                            icon="bi-archive-fill text-gray-500"
                            subtext="Clientes frios ou sem contato recente."
                        />
                    </div>
                </section>

                {/* 2. Área de Meta e Cálculo (Condicional) */}
                {!currentInputs ? (
                    <GoalInputScreen sellerName={currentReport.salesperson_name} onSetGoal={handleSetGoal} />
                ) : (
                    <div className="space-y-8 animate-fade-in-up">
                        {/* Resumo Calculado (Bento Style) */}
                        <section className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <div className="bg-gradient-to-br from-greatek-dark-blue to-greatek-blue p-5 rounded-xl text-white col-span-2 shadow-lg">
                                <p className="text-xs uppercase font-bold text-white/70 mb-1">Meta Faltante</p>
                                <h3 className="text-3xl font-bold">{formatCurrency(currentInputs.goal)}</h3>
                                <p className="text-xs mt-2 text-white/80">
                                    Para bater em <span className="font-bold text-white">{currentInputs.days} dias</span>
                                </p>
                            </div>
                            <div className="bg-white border border-gray-200 p-5 rounded-xl flex flex-col justify-center shadow-sm">
                                <p className="text-xs uppercase font-bold text-green-600 mb-1">Meta Diária (Venda)</p>
                                <h3 className="text-2xl font-bold text-gray-800">{formatCurrency(calculatedTargets!.dailySalesNeeded)}</h3>
                            </div>
                            <div className="bg-white border border-gray-200 p-5 rounded-xl flex flex-col justify-center shadow-sm">
                                <p className="text-xs uppercase font-bold text-blue-600 mb-1">Volume Diário (Ligações)</p>
                                <h3 className="text-2xl font-bold text-gray-800">{Math.ceil(calculatedTargets!.dailyCallsNeeded)}</h3>
                                <p className="text-[10px] text-gray-400 mt-1">Para gerar {Math.ceil(calculatedTargets!.dailyProposalsNeeded)} propostas/dia</p>
                            </div>
                        </section>

                        {/* Relatório Gerencial (Bento Grid) */}
                        <section>
                            <h3 className="text-lg font-bold text-greatek-dark-blue mb-4 flex items-center border-b border-gray-200 pb-2">
                                <i className="bi bi-briefcase-fill mr-2"></i>
                                Relatório Gerencial & Ação
                            </h3>

                            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 auto-rows-min">
                                {/* Estratégia - Large Box */}
                                <BentoGridItem className="lg:col-span-2" title="Estratégia de Abordagem" icon="bi-signpost-split-fill">
                                    <div className="prose prose-sm text-text-secondary whitespace-pre-wrap leading-relaxed">
                                        {currentReport.management_report.approach_strategy}
                                    </div>
                                </BentoGridItem>

                                {/* Performance - Side Box */}
                                <BentoGridItem title="Análise de Performance" icon="bi-graph-up-arrow" className="bg-gray-50 border-gray-200">
                                    <p className="text-sm text-text-secondary italic">"{currentReport.action_report.performance_analysis}"</p>
                                </BentoGridItem>

                                {/* Dicas Táticas */}
                                <BentoGridItem className="lg:col-span-1" title="Dicas Táticas" icon="bi-lightbulb-fill" headerColor="text-yellow-600">
                                    <ul className="space-y-3">
                                        {currentReport.management_report.coaching_tips.map((tip, idx) => (
