                                    <p className="text-sm text-text-secondary">{currentReport.management_report.contingency_plan}</p>
                                </BentoGridItem>
                            </div>
                        </section>

                        {/* Planejamento Semanal */}
                        <section>
                            <h3 className="text-lg font-bold text-greatek-dark-blue mb-4 flex items-center border-b border-gray-200 pb-2">
                                <i className="bi bi-calendar-week-fill mr-2"></i>
                                Planejamento Tático Semanal
                            </h3>
                            <WeeklyPlanBento plan={currentReport.action_report.weekly_planning} targets={calculatedTargets!} />
