            </main>

            {/* Modal de Email */}
            <Modal isOpen={isEmailModalOpen} onClose={() => setIsEmailModalOpen(false)} title={`Enviar Plano Hunter: ${currentReport.salesperson_name}`}>
                <div className="space-y-4">
                    <p className="text-sm text-text-secondary">
                        Envie o plano tático com as metas diárias calculadas (ligações e propostas) para o vendedor.
                    </p>
                    <div>
                        <label className="block text-sm font-semibold text-greatek-dark-blue mb-1">E-mail do Vendedor</label>
                        <input 
                            type="email" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="vendedor@greatek.com.br"
                            className="w-full p-3 border border-greatek-border rounded-lg bg-[#e9e9e9] text-black"
                        />
