    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.setTextColor(colors.greatekDarkBlue[0], colors.greatekDarkBlue[1], colors.greatekDarkBlue[2]);
    doc.text("Dicas Táticas & Coaching", margin, finalY);
    finalY += 7;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    report.management_report.coaching_tips.forEach(tip => {
        const tipLines = doc.splitTextToSize(`• ${tip}`, pageW - margin * 2);
        doc.text(tipLines, margin, finalY);
        finalY += (tipLines.length * 5) + 2;
    });

    // Save
    doc.save(`Relatorio_Gerencial_${report.salesperson_name.replace(/\s+/g, '_')}.pdf`);
};

export const generateQuizResultPdf = (
    productName: string,
    quiz: QuizQuestion[],
    userAnswers: (string | null)[],
    score: number
) => {
    const doc = new jsPDF();
    const margin = 15;
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    let finalY = 20;

    const colors = {
        greatekDarkBlue: [8, 63, 98],
        greatekBlue: [0, 129, 204],
        textPrimary: [11, 11, 11],
        textSecondary: [74, 74, 74],
        border: [233, 233, 233],
        correctGreen: [34, 139, 34],
        correctGreenBg: [230, 245, 230],
        incorrectRed: [220, 20, 60],
        incorrectRedBg: [255, 235, 238],
        correctAnswerBg: [240, 240, 240],
    };

    const checkPageBreak = (neededHeight: number) => {
        if (finalY + neededHeight > pageH - margin) {
            doc.addPage();
            finalY = 20;
        }
    };

    // --- Header ---
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(18);
    doc.setTextColor(colors.greatekDarkBlue[0], colors.greatekDarkBlue[1], colors.greatekDarkBlue[2]);
    doc.text('Resultado do Quiz de Conhecimento', margin, finalY);
    finalY += 8;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(12);
    doc.setTextColor(colors.textSecondary[0], colors.textSecondary[1], colors.textSecondary[2]);
    doc.text(`Produto: ${productName || 'Não especificado'}`, margin, finalY);
    finalY += 15;

    // --- Bento Grid Summary ---
    checkPageBreak(50);
    const correctCount = quiz.filter((q, i) => q.correct_answer === userAnswers[i]).length;
    const boxWidth = (pageW - margin * 2 - 10) / 2;

    // Score Box
    doc.setFillColor(colors.greatekBlue[0], colors.greatekBlue[1], colors.greatekBlue[2]);
    doc.roundedRect(margin, finalY, boxWidth, 40, 3, 3, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text('PONTUAÇÃO FINAL', margin + 10, finalY + 15);
    doc.setFontSize(18);
    doc.text(`${score}%`, margin + 10, finalY + 30);

    // Correct Answers Box
    doc.setFillColor(255, 255, 255);
    doc.setDrawColor(colors.border[0], colors.border[1], colors.border[2]);
    doc.roundedRect(margin + boxWidth + 10, finalY, boxWidth, 40, 3, 3, 'FD');
    doc.setTextColor(colors.textSecondary[0], colors.textSecondary[1], colors.textSecondary[2]);
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text('ACERTOS', margin + boxWidth + 20, finalY + 15);
    doc.setFontSize(18);
    doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
    doc.text(`${correctCount} / ${quiz.length}`, margin + boxWidth + 20, finalY + 30);

    finalY += 55;

    // --- Question Cards ---
    doc.setFont('helvetica', 'normal');

    quiz.forEach((q, index) => {
        const userAnswer = userAnswers[index];
        const isCorrect = q.correct_answer === userAnswer;

        // FIX: Declare correctAnswerLines here to make it available in the whole scope.
        let correctAnswerLines: string[] = [];

        // Calculate card height before drawing
        let cardHeight = 10; // top padding
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(11);
        const questionLines = doc.splitTextToSize(`${index + 1}. ${q.question}`, pageW - margin * 2 - 20);
        cardHeight += questionLines.length * 5;

        cardHeight += 10; // space before answer

        // User answer box height
        doc.setFontSize(10);
        const userAnswerText = `Sua resposta: ${userAnswer || 'Não respondida'}`;
        const userAnswerLines = doc.splitTextToSize(userAnswerText, pageW - margin * 2 - 40);
        cardHeight += (userAnswerLines.length * 5) + 8; // text + padding

        // Correct answer box height (if incorrect)
        if (!isCorrect) {
            const correctAnswerText = `Resposta correta: ${q.correct_answer}`;
            correctAnswerLines = doc.splitTextToSize(correctAnswerText, pageW - margin * 2 - 40);
            cardHeight += (correctAnswerLines.length * 5) + 8 + 4; // text + padding + margin
        }

        cardHeight += 10; // space before explanation

        // Explanation height
        doc.setFontSize(9);
        doc.setFont('helvetica', 'italic');
        const explanationText = `Justificativa: ${q.explanation}`;
        const explanationLines = doc.splitTextToSize(explanationText, pageW - margin * 2 - 20);
        cardHeight += (explanationLines.length * 4) + 8;
        cardHeight += 5; // bottom padding
        doc.setFont('helvetica', 'normal');

        checkPageBreak(cardHeight);
        let cardY = finalY;

        // Draw Card border
        doc.setLineWidth(1);
        doc.setDrawColor(isCorrect ? colors.correctGreen[0] : colors.incorrectRed[0], isCorrect ? colors.correctGreen[1] : colors.incorrectRed[1], isCorrect ? colors.correctGreen[2] : colors.incorrectRed[2]);
        doc.roundedRect(margin, cardY, pageW - margin * 2, cardHeight, 3, 3, 'S');
        cardY += 10;

        // Question
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(11);
        doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
        doc.text(questionLines, margin + 10, cardY);
        cardY += (questionLines.length * 5) + 10;

        // User Answer Box
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        doc.setFillColor(isCorrect ? colors.correctGreenBg[0] : colors.correctGreenBg[1], isCorrect ? colors.correctGreenBg[2] : colors.incorrectRedBg[2], isCorrect ? colors.correctGreenBg[2] : colors.incorrectRedBg[2]);
        doc.roundedRect(margin + 10, cardY - 4, pageW - margin * 2 - 20, (userAnswerLines.length * 5) + 8, 2, 2, 'F');
        doc.setTextColor(isCorrect ? colors.correctGreen[0] : colors.incorrectRed[0], isCorrect ? colors.correctGreen[1] : colors.incorrectRed[1], isCorrect ? colors.correctGreen[2] : colors.incorrectRed[2]);
        doc.setFont('helvetica', 'bold');
        doc.text(isCorrect ? '✓' : '✗', margin + 15, cardY + 2);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
        doc.text(userAnswerLines, margin + 25, cardY + 2);
        cardY += (userAnswerLines.length * 5) + 8;

        // Correct Answer Box (if incorrect)
        if (!isCorrect) {
            cardY += 4;
            doc.setFillColor(colors.correctAnswerBg[0], colors.correctAnswerBg[1], colors.correctAnswerBg[2]);
            doc.roundedRect(margin + 10, cardY - 4, pageW - margin * 2 - 20, (correctAnswerLines.length * 5) + 8, 2, 2, 'F');
            doc.setTextColor(colors.correctGreen[0], colors.correctGreen[1], colors.correctGreen[2]);
            doc.setFont('helvetica', 'bold');
            doc.text('✓', margin + 15, cardY + 2);
            doc.setFont('helvetica', 'normal');
            doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
            doc.text(correctAnswerLines, margin + 25, cardY + 2);
            cardY += (correctAnswerLines.length * 5) + 8;
        }

        // Explanation
        cardY += 10;
        doc.setDrawColor(colors.border[0], colors.border[1], colors.border[2]);
        doc.line(margin + 10, cardY - 5, pageW - margin - 10, cardY - 5);
        doc.setFontSize(9);
        doc.setFont('helvetica', 'italic');
        doc.setTextColor(colors.textSecondary[0], colors.textSecondary[1], colors.textSecondary[2]);
        doc.text(explanationLines, margin + 10, cardY);

        finalY += cardHeight + 10;
    });

    const sanitizedTitle = `Resultado_Quiz_${(productName || 'Produto').replace(/[^a-zA-Z0-9]/g, '_')}`;
    doc.save(`${sanitizedTitle}.pdf`);
};

export const generateTrainingReportPdf = (report: TrainingAnalysisReport, product: string) => {
    const doc = new jsPDF();
    const margin = 15;
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    let finalY = 20;

    const colors = {
        greatekDarkBlue: [8, 63, 98],
        greatekBlue: [0, 129, 204],
        textPrimary: [11, 11, 11],
        textSecondary: [74, 74, 74],
        border: [233, 233, 233],
        green: [46, 125, 50],
        greenBg: [232, 245, 233],
        yellow: [245, 127, 23],
        yellowBg: [255, 243, 224],
        red: [198, 40, 40],
        redBg: [255, 235, 238],
    };

    const checkPageBreak = (neededHeight: number) => {
        if (finalY + neededHeight > pageH - margin) {
            doc.addPage();
            finalY = 20;
        }
    };

    // --- Header ---
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(18);
    doc.setTextColor(colors.greatekDarkBlue[0], colors.greatekDarkBlue[1], colors.greatekDarkBlue[2]);
    doc.text('Relatório de Performance - Coach de Treinamento', margin, finalY);
    finalY += 8;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(colors.textSecondary[0], colors.textSecondary[1], colors.textSecondary[2]);
    doc.text(`Produto Treinado: ${product || 'Não especificado'}`, margin, finalY);
    finalY += 15;

    // --- Score and Summary ---
    checkPageBreak(50);
    const scoreColor = report.score >= 8 ? colors.green : report.score >= 5 ? colors.yellow : colors.red;

    // Score Circle
    doc.setLineWidth(2.5);
    doc.setDrawColor(scoreColor[0], scoreColor[1], scoreColor[2]);
    doc.circle(margin + 20, finalY + 15, 20);
    doc.setFontSize(24);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(scoreColor[0], scoreColor[1], scoreColor[2]);
    doc.text(report.score.toFixed(0), margin + 20, finalY + 18, { align: 'center' });

    // Summary Text
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(colors.greatekDarkBlue[0], colors.greatekDarkBlue[1], colors.greatekDarkBlue[2]);
    const summaryX = margin + 50;
    const summaryMaxWidth = pageW - summaryX - margin;
    doc.text('Resumo do Coach', summaryX, finalY);
    finalY += 6;
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(colors.textSecondary[0], colors.textSecondary[1], colors.textSecondary[2]);
    const summaryLines = doc.splitTextToSize(report.summary, summaryMaxWidth);
    doc.text(summaryLines, summaryX, finalY);
    finalY += (summaryLines.length * 5) + 10;

    // --- Strengths & Improvements (side by side) ---
    checkPageBreak(60);
    const colWidth = (pageW - margin * 2 - 10) / 2;
    const strengthsY = finalY;
    const improvementsY = finalY;

    // Strengths
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(colors.green[0], colors.green[1], colors.green[2]);
    doc.text('Pontos Fortes', margin, strengthsY);
    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
    let currentYStrengths = strengthsY + 7;
    report.strengths.forEach(item => {
        const itemLines = doc.splitTextToSize(`• ${item}`, colWidth - 5);
        if (currentYStrengths + (itemLines.length * 4) > finalY + 50) { // crude check to avoid overflow in this simple layout
             // In a real scenario, you'd calculate the max height of both columns first
        }
        doc.text(itemLines, margin, currentYStrengths);
        currentYStrengths += (itemLines.length * 4) + 2;
    });

    // Improvements
    const improvementsX = margin + colWidth + 10;
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(colors.yellow[0], colors.yellow[1], colors.yellow[2]);
    doc.text('Pontos a Melhorar', improvementsX, improvementsY);
    doc.setFontSize(9);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
    let currentYImprovements = improvementsY + 7;
    report.areas_for_improvement.forEach(item => {
        const itemLines = doc.splitTextToSize(`• ${item}`, colWidth - 5);
        doc.text(itemLines, improvementsX, currentYImprovements);
        currentYImprovements += (itemLines.length * 4) + 2;
    });

    finalY = Math.max(currentYStrengths, currentYImprovements) + 10;

    // --- Strategic Suggestions ---
    checkPageBreak(15);
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(colors.greatekDarkBlue[0], colors.greatekDarkBlue[1], colors.greatekDarkBlue[2]);
    doc.text('Sugestões Estratégicas', margin, finalY);
    finalY += 8;

    const drawCard = (title: string, text: string, titleColor: number[], bgColor: number[]) => {
        doc.setFontSize(10);
        doc.setFont('helvetica', 'bold');
        const titleLines = doc.splitTextToSize(title, pageW - margin * 2 - 20);

        doc.setFontSize(9);
        doc.setFont('helvetica', 'normal');
        const textLines = doc.splitTextToSize(text, pageW - margin * 2 - 20);

        const cardHeight = 10 + (titleLines.length * 5) + 3 + (textLines.length * 4) + 5;
        checkPageBreak(cardHeight);

        doc.setFillColor(bgColor[0], bgColor[1], bgColor[2]);
        doc.roundedRect(margin, finalY, pageW - margin * 2, cardHeight, 3, 3, 'F');

        let cardContentY = finalY + 8;
        doc.setFontSize(10);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(titleColor[0], titleColor[1], titleColor[2]);
        doc.text(titleLines, margin + 10, cardContentY);
        cardContentY += (titleLines.length * 5) + 3;

        doc.setFontSize(9);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(colors.textPrimary[0], colors.textPrimary[1], colors.textPrimary[2]);
        doc.text(textLines, margin + 10, cardContentY);

        finalY += cardHeight + 5;
    }

    report.suggested_arguments.forEach(arg => {
        drawCard(arg.title, arg.explanation, colors.greatekDarkBlue, [227, 242, 253]); // light blue bg
    });

    report.objection_handling.forEach(obj => {
        drawCard(`Como Contornar: "${obj.objection}"`, obj.suggestion, colors.red, colors.redBg);
    });

    const sanitizedTitle = `Relatorio_Performance_${(product || 'Produto').replace(/[^a-zA-Z0-9]/g, '_')}`;
    doc.save(`${sanitizedTitle}.pdf`);
};

import React, { useState, useMemo, useEffect } from 'react';
import { OutboundReport, OutboundDailyPlan, OutboundGoalInputs } from '../types';
import Modal from './ui/Modal';
import { useAppStore } from '../store/useAppStore';
import { generateOutboundManagerialPdf } from '../services/pdfGenerator';

const formatCurrency = (value: number) => {
    return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

interface CalculatedTargets {
    dailySalesNeeded: number; // Valor R$
    dailyDealsNeeded: number; // Qtd Vendas
    dailyProposalsNeeded: number; // Qtd Propostas
    dailyCallsNeeded: number; // Qtd Ligações
}

// ---- DENSE COMPONENT UI HELPERS ----

