    }
  }, [editingConvId]);

  useEffect(() => {
    if (isOpen) {
      setMenuOpenFor(null);
    }
  }, [isOpen]);

  const sortedConversations = [...conversations].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

